 csrf_check();try{
  if(($_POST['action']??'')==='delete'&&$id){$pdo->prepare('DELETE FROM eco_editable_offers WHERE id=?')->execute([$id]);redirect('/editable-offers/');}
  $keys=['number','offer_date','language','currency','customer','invoice_address','delivery_address','vat_number','email','phone','payment_terms','delivery_terms','price_terms','our_ref','file_link','discount_percent','transport_cost','transport_note','notes'];$vals=[];
  foreach($keys as $key){$v=trim((string)($_POST[$key]??''));$vals[]=in_array($key,['discount_percent','transport_cost'],true)&&$v===''?null:$v;}
  if(!$vals[0])$vals[0]='ECO-'.date('Ymd-His');if(!$vals[1])$vals[1]=date('Y-m-d');if(!in_array($vals[2],['ro','en','it'],true))$vals[2]='ro';if(!in_array($vals[3],['EUR','RON'],true))$vals[3]='EUR';
  $pdo->beginTransaction();if($id){$set=implode(',',array_map(fn($k)=>$k.'=?',$keys));$pdo->prepare("UPDATE eco_editable_offers SET $set WHERE id=?")->execute([...$vals,$id]);}else{$pdo->prepare('INSERT INTO eco_editable_offers('.implode(',',$keys).') VALUES ('.implode(',',array_fill(0,count($keys),'?')).')')->execute($vals);$id=(int)$pdo->lastInsertId();}
  $previous=eco_offer_items($pdo,$id);$oldImages=[];foreach($previous as $item)$oldImages[(int)$item['id']]=$item['image_path'];
  $pdo->prepare('DELETE FROM eco_editable_offer_items WHERE offer_id=?')->execute([$id]);
  $refs=$_POST['item_reference']??[];$names=$_POST['item_name']??[];$descs=$_POST['item_description']??[];$prices=$_POST['item_price']??[];$qtys=$_POST['item_quantity']??[];$free=$_POST['item_free']??[];$images=$_POST['item_existing_image']??[];$parents=$_POST['item_parent']??[];
  $insert=$pdo->prepare('INSERT INTO eco_editable_offer_items(offer_id,parent_id,reference,name,description,image_path,price,quantity,is_free,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?)');
  foreach($names as $i=>$name){$name=trim((string)$name);if($name==='')continue;$image=(string)($images[$i]??'');if($image!==''&&!in_array($image,$oldImages,true))$image='';if(isset($_FILES['item_image']['error'][$i])&&$_FILES['item_image']['error'][$i]===UPLOAD_ERR_OK){$f=[];foreach(['name','type','tmp_name','error','size'] as $k)$f[$k]=$_FILES['item_image'][$k][$i];$image=eco_upload_image($f);}
   $insert->execute([$id,($parents[$i]??'')!==''?(int)$parents[$i]:null,trim((string)($refs[$i]??'')),$name,(string)($descs[$i]??''),$image,max(0,(float)($prices[$i]??0)),max(0,(float)($qtys[$i]??1)),isset($free[$i])?(int)$free[$i]:0,$i]);}
  $pdo->commit();flash('success','Oferta a fost salvată.');redirect('/editable-offers/');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
