<script>
(()=>{let next=<?=count($items)?>;const list=document.getElementById('items'),tpl=document.getElementById('itemTemplate');function add(addon=false){const el=tpl.content.firstElementChild.cloneNode(true),i=next++;el.querySelectorAll('[data-field]').forEach(x=>{x.name='item_'+x.dataset.field+'['+i+']';});if(addon)el.querySelector('[data-field="parent"]').value='1';list.append(el);calc();}function calc(){let sum=0;list.querySelectorAll('.eco-item').forEach(el=>{let price=Number(el.querySelector('.item-price').value||0),qty=Number(el.querySelector('.item-qty').value||0),free=el.querySelector('[type="checkbox"]').checked,v=free?0:price*qty;sum+=v;el.querySelector('.eco-item-total strong').textContent=v.toFixed(2)});let discount=sum*Math.min(100,Math.max(0,Number(document.getElementById('discount').value||0)))/100;document.getElementById('subtotal').textContent=sum.toFixed(2);document.getElementById('discountTotal').textContent=discount.toFixed(2);document.getElementById('grandTotal').textContent=(sum-discount+Number(document.getElementById('transport').value||0)).toFixed(2)}document.getElementById('addItem').onclick=()=>add();document.getElementById('addAddon').onclick=()=>add(true);document.getElementById('offerForm').addEventListener('input',calc);list.addEventListener('click',e=>{if(e.target.closest('.eco-remove')){e.target.closest('.eco-item').remove();calc()}});const lang=document.getElementById('ecoLanguage');function translate(){document.querySelectorAll('[data-ro][data-en]').forEach(el=>{const t=lang.value==='en'?el.dataset.en:lang.value==='it'?(el.dataset.it||el.dataset.en):el.dataset.ro;const child=[...el.childNodes].find(n=>n.nodeType===3&&n.textContent.trim());if(child)child.textContent=t;});}lang.addEventListener('change',translate);translate();if(!list.children.length)add();calc()})();
</script>
